cardCss:
.word-card {
    background: var(--card-bg, #ffffff);
    border-radius: 16px;
    padding: 14px 18px;
    box-shadow: 0 1px 2px rgba(15,118,110,0.06), 0 6px 16px rgba(15,118,110,0.07);
    border: 1px solid var(--line, #e6e6e6);
    border-left: 4px solid var(--primary, #0f766e); min-height: 260px; display: flex; flex-direction: column;
    transition: transform 0.25s, box-shadow 0.25s, border-color 0.25s;
    margin-bottom: 16px;
}
.word-card:hover {
    transform: translateY(-3px);
    box-shadow: 0 10px 26px rgba(15, 118, 110, 0.10);
    border-color: var(--primary-soft, #ccfbf1);
}
.word-card.highlighted { border-left-color: var(--unknown, #f43f5e); background: #fef6f3; }
.word-card:active { transform: scale(0.99); }
.word-card.enter { animation: cardIn 0.5s both; }
@keyframes cardIn {
    from { opacity: 0; transform: translateY(14px) scale(0.99); }
    to   { opacity: 1; transform: none; }
}

.card-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 8px; gap: 8px; }
.word-basic { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.word-index { color: var(--ink-3, #64748b); font-weight: var(--card-font-weight, 600); font-size: calc(12px * var(--scale-basic, 1) * var(--card-font-scale, 1)); }
.word-title { font-weight: var(--card-font-weight, 700); color: #15803d; letter-spacing: -0.3px; font-size: calc(22px * var(--scale-basic, 1) * var(--card-font-scale, 1)); }
.word-phonetic { color: var(--ink-2, #475569); font-size: calc(13px * var(--scale-basic, 1) * var(--card-font-scale, 1)); }

.actions { display: flex; gap: 10px; }
.action-btn {
    cursor: pointer; transition: all 0.2s; width: 44px; height: 44px;
    display: flex; align-items: center; justify-content: center;
    border-radius: 90px; background: var(--action-btn-bg, #f1f5f9);
    color: var(--ink-3, #64748b); border: none;
}
.action-btn svg, .action-btn i { width: 28px; height: 28px; transition: transform 0.18s; }
.action-btn:hover { background: var(--primary, #0f766e); color: #fff; box-shadow: 0 4px 12px var(--primary-ring, rgba(15,118,110,0.3)); transform: translateY(-2px); }
.action-btn:hover svg { transform: scale(1.12); }
.action-btn:active { transform: scale(0.88); }
.action-btn.act-play:hover { background: var(--primary, #0f766e); color: #fff; box-shadow: 0 4px 12px var(--primary-ring, rgba(15,118,110,0.3)); }
.action-btn.act-eye:hover { background: var(--amber-soft, #fef3c7); color: var(--amber, #d97706); box-shadow: 0 4px 12px var(--amber-ring, rgba(217,119,6,0.3)); }
.action-btn.act-mark:hover { background: var(--unknown-soft, #ffe4e6); color: var(--unknown, #f43f5e); box-shadow: 0 4px 12px var(--unknown-ring, rgba(244,63,94,0.3)); }
.action-btn.act-mark.is-active { background: var(--unknown, #f43f5e); color: #fff; box-shadow: 0 4px 14px var(--unknown-ring, rgba(244,63,94,0.3)); }
.action-btn.act-fav:hover { background: var(--amber-soft, #fef3c7); color: var(--amber, #d97706); box-shadow: 0 4px 12px var(--amber-ring, rgba(217,119,6,0.3)); }
.action-btn.act-fav.is-active { background: var(--amber, #d97706); color: #fff; box-shadow: 0 4px 12px var(--amber-ring, rgba(217,119,6,0.3)); }

.definition { margin-bottom: 6px; padding: 6px 8px; border-radius: 6px; background-color: var(--def-bg, #e6f0e8); }
.def-en { color: var(--ink, #1d1d1d); line-height: 1.4; margin-bottom: 3px; font-size: calc(13px * var(--scale-def, 1) * var(--card-font-scale, 1)); }
.def-cn { color: var(--ink, #1d1d1d); line-height: 1.4; font-size: calc(13px * var(--scale-def, 1) * var(--card-font-scale, 1)); }

.divider { height: 1px; background-color: var(--line, #e6e6e6); margin: 6px 0; }

.examples { display: flex; flex-direction: column; gap: 6px; }
.example-item { display: flex; flex-direction: column; gap: 4px; padding: 6px 8px; border-radius: 6px; background-color: var(--ex-bg, #fdf8e8); }
.ex-en { color: var(--ink, #1d1d1d); line-height: 1.4; font-size: calc(12px * var(--scale-example, 1) * var(--card-font-scale, 1)); }
.ex-cn { color: var(--ink, #1d1d1d); line-height: 1.4; font-size: calc(12px * var(--scale-example, 1) * var(--card-font-scale, 1)); }

.action-btn.example-toggle-btn { width: 44px; height: 44px; border-radius: 90px; background: var(--amber-soft, #fef3c7); color: var(--amber, #d97706); }
.action-btn.example-toggle-btn:hover { background: #fde9c2; transform: translateY(-2px); box-shadow: 0 4px 12px var(--amber-ring, rgba(217,119,6,0.3)); color: var(--amber, #d97706); }
.action-btn.example-toggle-btn.active { background: linear-gradient(135deg, var(--amber, #d97706), #b45309); color: #fff; }

/* All fields visible by default; eye button toggles Chinese translation */
.eye-btn { display: flex; }
.def-cn { display: block; }
.ex-cn { display: block; }
.def-cn.hide { display: none; }
.ex-cn.hide { display: none; }
.act-eye.is-active { background: var(--amber-soft, #fef3c7); color: var(--amber, #d97706); }
.action-btn i { font-size: 18px; line-height: 1; }
.action-btn:hover i { transform: scale(1.1); }

cardJs:
(function () {
    'use strict';
    function formatParaphrase(text) {
        if (!text) return '';
        try {
            var arr = JSON.parse(text);
            if (Array.isArray(arr)) return arr.join('<br>');
        } catch (e) {}
        return text;
    }
    window.cardTemplate = {
        name: 'English Word Card',
        fields: [
            { key: 'word', label: 'Word', hideable: false },
            { key: 'phonetic_us', label: 'Phonetic' },
            { key: 'paraphrase_en', label: 'English Definition' },
            { key: 'paraphrase_zh', label: 'Chinese Definition' },
            { key: 'examples', label: 'Examples' }
        ],
        render: function (cardHtml, cardData, api) {
            var data = api.getCardData ? api.getCardData() : cardData;
            var hidden = (api.getHiddenFields && api.getHiddenFields()) || {};
            function isHidden(key) { return hidden.has && hidden.has(key); }
            function wrap(key, content) { return isHidden(key) ? '' : content; }
            var markActive = data.is_unknown === 1 ? 'is-active' : '';
            var favActive = data.is_favorite === 1 ? 'is-active' : '';
            var showDef = data._showDef === true;
            var defHide = showDef ? '' : 'hide';
            var eyeActive = showDef ? 'is-active' : '';
            var examplesHtml = '';
            if (!isHidden('examples') && data.data && data.data.examples && data.data.examples.length) {
                examplesHtml += '<div class="divider"></div><div class="examples">';
                data.data.examples.forEach(function (ex, idx) {
                    var showEx = ex._show === true;
                    var exHide = showEx ? '' : 'hide';
                    var btnActive = showEx ? 'active' : '';
                    examplesHtml += '<div class="example-item">';
                    examplesHtml += '<div style="display:flex;justify-content:space-between;align-items:center;gap:8px;">';
                    examplesHtml += '<div class="ex-en" style="flex:1;word-wrap:break-word;word-break:break-word;">' + (ex.en || '') + '</div>';
                    examplesHtml += '<button class="action-btn eye-btn example-toggle-btn ' + btnActive + '" data-action="toggle-ex" data-ex-idx="' + idx + '" data-tooltip="Show Translation"><i class="fa-solid fa-eye"></i></button></div>';
                    examplesHtml += '<div class="ex-cn ' + exHide + '">' + (ex.zh || '') + '</div>';
                    examplesHtml += '</div>';
                });
                examplesHtml += '</div>';
            }
            var html = '<div class="word-card ' + (data.is_unknown === 1 ? 'highlighted' : '') + '" data-card-id="' + data.id + '">';
            html += '<div class="card-header"><div class="word-basic">';
            html += '<span class="word-index">' + String(data.current_order).padStart(2, '0') + '</span>';
            html += wrap('word', '<span class="word-title">' + (data.data && data.data.word || '') + '</span>');
            html += wrap('phonetic_us', '<span class="word-phonetic">' + (data.data && data.data.phonetic_us || '') + '</span>');
            html += '</div><div class="actions">';
            html += '<button class="action-btn act-play" data-action="play" data-tooltip="Play Pronunciation"><i class="fa-solid fa-volume-high"></i></button>';
            html += '<button class="action-btn eye-btn act-eye ' + eyeActive + '" data-action="toggle-def" data-tooltip="Toggle Chinese"><i class="' + (showDef ? 'fa-solid' : 'fa-regular') + ' fa-eye"></i></button>';
            html += '<button class="action-btn act-mark ' + markActive + '" data-action="mark" data-tooltip="Mark as Unknown"><i class="' + (data.is_unknown === 1 ? 'fa-solid' : 'fa-regular') + ' fa-star"></i></button>';
            html += '<button class="action-btn act-fav ' + favActive + '" data-action="favorite" data-tooltip="Favorite"><i class="' + (data.is_favorite === 1 ? 'fa-solid' : 'fa-regular') + ' fa-bookmark"></i></button>';
            html += '</div></div>';
            if (!isHidden('paraphrase_en') || !isHidden('paraphrase_zh')) {
                html += '<div class="definition">';
                html += wrap('paraphrase_en', '<div class="def-en">' + formatParaphrase(data.data && data.data.paraphrase_en) + '</div>');
                html += wrap('paraphrase_zh', '<div class="def-cn ' + defHide + '">' + formatParaphrase(data.data && data.data.paraphrase_zh) + '</div>');
                html += '</div>';
            }
            html += examplesHtml;
            html += '</div>';
            return html;
        },
        init: function (cardElement, cardData, api) {
            api.track("definition_view");
            cardElement.querySelector('[data-action="play"]').addEventListener('click', function () {
                var w = cardData.data && cardData.data.word;
                if (w) api.playAudio(w);
                api.track('audio_play');
            });
            cardElement.querySelector('[data-action="toggle-def"]').addEventListener('click', function () {
                if (cardData._showDef) {
                    clearTimeout(cardData._defTimer);
                    cardData._showDef = false;
                    api.rerender();
                } else {
                    cardData._showDef = true;
                    clearTimeout(cardData._defTimer);
                    cardData._defTimer = setTimeout(function () {
                        cardData._showDef = false;
                        api.rerender();
                    }, 5000);
                    api.rerender();
                }
            });
            cardElement.querySelector('[data-action="mark"]').addEventListener('click', function () {
                api.toggleMark().then(function () { api.rerender(); });
                api.track('word_mark');
            });
            var favBtn = cardElement.querySelector('[data-action="favorite"]');
            if (favBtn) {
                favBtn.addEventListener('click', function () {
                    api.toggleFavorite().then(function () { api.rerender(); });
                    api.track('favorite_toggle');
                });
            }
            cardElement.querySelectorAll('[data-action="toggle-ex"]').forEach(function (btn) {
                btn.addEventListener('click', function () {
                    var idx = parseInt(btn.dataset.exIdx);
                    var ex = cardData.data && cardData.data.examples && cardData.data.examples[idx];
                    if (!ex) return;
                    if (ex._show) {
                        clearTimeout(ex._timer);
                        ex._show = false;
                        api.rerender();
                    } else {
                        ex._show = true;
                        clearTimeout(ex._timer);
                        ex._timer = setTimeout(function () {
                            ex._show = false;
                            api.rerender();
                        }, 5000);
                        api.rerender();
                        api.track('example_view');
                    }
                });
            });
            cardElement.querySelectorAll('[data-action]').forEach(function (btn) {
                btn.addEventListener('mouseenter', function () {
                    var tooltip = btn.dataset.tooltip;
                    if (tooltip && api.showTooltip) api.showTooltip(btn, tooltip);
                });
                btn.addEventListener('mouseleave', function () {
                    if (api.hideTooltip) api.hideTooltip();
                });
            });
        },
        update: function (cardElement, cardData, api) {
            var p = cardElement.parentElement;
            if (p) { cardElement.outerHTML = this.render('', cardData, api); }
        }
    };
})();
